package org.appliedtopology.tda4j

import scala.collection.immutable.ArraySeq
import scala.collection.mutable

/** Vietoris-Rips, each dimension generated from the one below already in filtration order, so nothing above the edges
  * is sorted (Bauer, Matuszewski and Vejdemo-Johansson, "Generating cofaces in Vietoris-Rips filtration order",
  * arXiv:2411.05495, Theorem 3 and Proposition 7).
  *
  * A simplex of diameter `α` is generated by exactly one of its facets, which has the same diameter, so walking
  * dimension `d` in filtration order and emitting each simplex's same-diameter cofacets walks dimension `d + 1` in
  * filtration order. Each simplex carries its first longest edge, which its cofacets inherit unchanged and which
  * decides the vertices it may add. Ties are listed colexicographically descending, as
  * [[EnumeratingCofaceSimplexStream]] lists them: same cells, values and order. `maxFiltrationValue` defaults to the
  * minimum enclosing radius.
  *
  * Every dimension built so far is kept, as primitive arrays ([[LayeredInorderSimplexStream.Layer]]).
  */
open class LayeredInorderSimplexStream(
  metricSpace: FiniteMetricSpace[Int],
  maxFiltrationValue: Option[Double] = None,
  val candidates: LayeredInorderSimplexStream.Candidates = LayeredInorderSimplexStream.Candidates.Bitsets
) extends EnumeratingCofaceSimplexStream(metricSpace, maxFiltrationValue = maxFiltrationValue):
  import LayeredInorderSimplexStream.*

  lazy val generator: Generator =
    Generator(metricSpace.size, distanceOf(metricSpace), resolvedMaxFiltrationValue, candidates)

  private val layers = mutable.ArrayBuffer.empty[Layer]

  /** Dimension `d >= 1`, building the dimensions below it first if they are not built yet. */
  def layer(d: Int): Layer =
    require(d >= 1, s"layers start at the edges (d = 1), got $d")
    if layers.isEmpty then layers += generator.edges
    while layers.size < d do layers += generator.cofacets(layers.last)
    layers(d - 1)

  override def iterateDimension: PartialFunction[Int, Iterator[Simplex[Int]]] = {
    case 0                                   => metricSpace.elements.iterator.map(v => Simplex(v))
    case d if d >= 1 && d < metricSpace.size =>
      val l = layer(d)
      Iterator.range(0, l.size).map(l.simplex)
  }

object LayeredInorderSimplexStream:

  /** `space.distance` as a function of two `Int`s that does not box them: a call through `FiniteMetricSpace[Int]` goes
    * to the generic `distance(VertexT, VertexT)` and allocates two `Integer`s per pair, which the pass over all
    * `n^2 / 2` pairs of [[Generator]] pays for, while a class that declares `distance(Int, Int)` is called directly.
    */
  def distanceOf(space: FiniteMetricSpace[Int]): (Int, Int) => Double = space match
    case euclidean: EuclideanMetricSpace => (a, b) => euclidean.distance(a, b)
    case explicit: ExplicitMetricSpace   => (a, b) => explicit.distance(a, b)
    case other                           => (a, b) => other.distance(a, b)

  /** How the candidate vertices of a simplex (those within its diameter of all its vertices) are found. */
  enum Candidates:
    /** Each vertex's ball as a bitset row, the rows updated by a sweep over the sorted edges; candidates are a
      * word-wise AND of the rows of the simplex's vertices, read from the top down. Two `n × n` bit matrices.
      */
    case Bitsets

    /** Each vertex's neighbours sorted by distance, its ball the prefix up to a pointer that only moves forward along a
      * dimension; candidates come from scanning the smallest ball among the simplex's vertices and looking up the other
      * distances.
      */
    case NeighbourLists

  /** One dimension in filtration order. Simplex `i` has the ascending vertices `vertices(i * (dim + 1) until (i + 1) *
    * (dim + 1))`; its first longest edge is edge `root(i)` of the generator's edge list, and that edge's length is its
    * diameter.
    */
  open class Layer(val dim: Int, val size: Int, val vertices: Array[Int], val root: Array[Int]):
    def simplex(i: Int): Simplex[Int] =
      Simplex.from(ArraySeq.unsafeWrapArray(java.util.Arrays.copyOfRange(vertices, i * (dim + 1), (i + 1) * (dim + 1))))

  /** Builds the layers of the flag complex of a weighted graph on the vertices `0 until n`, up to `threshold`: a set of
    * vertices is a simplex when all its pairs are edges, and its value is the largest edge weight, the diameter in the
    * paper. Vietoris-Rips is the graph with an edge for every pair within `threshold` ([[Generator]]).
    *
    * The paper writes vertices in decreasing order and lets the facet without the largest vertex generate a simplex
    * when it can. Here vertices ascend and the smallest vertex plays that part, which makes simplices with the same
    * first longest edge come out colexicographically descending. For a simplex `u0 < u1 < ... < uk` of diameter `α`
    * whose first longest edge (the full-length edge `a < b` with the largest `a`, then the largest `b`) is `ab`:
    *   1. any `w < u0` within `α` of every vertex gives `w u0 ... uk`;
    *   2. if `a = u0` (every full-length edge contains `u0`), any `u0 < w < u1` within `α` of `u0` and closer than `α`
    *      to the rest gives `u0 w u1 ... uk`;
    *   3. if moreover `b = u1` (the only full-length edge is `u0 u1`), any `u1 < w < u2` (any `w > u1` for an edge)
    *      closer than `α` to every vertex gives `u0 u1 w u2 ... uk`.
    *
    * In each case the new simplex keeps the first longest edge `ab`, so the diameter is never recomputed. The
    * candidates are emitted largest first. On points in general position (no two distances equal) that is already the
    * colexicographically descending order of each tie; elsewhere a run of equal diameters that comes out of order is
    * sorted, and counted in `tieRunsSorted`.
    *
    * Only the edge weights are read, so any flag filtration whose simplices take the largest weight of their edges can
    * be built with it. A vertex `w` can also leave: with `deadline(w) < α` the vertex is added to no simplex of value
    * `α` (Sheehy's sparse Rips complex, where a point vanishes from the nerve after a scale); an empty `deadline` means
    * no vertex does. A vertex's own value never matters for the layers from dimension 1 on, provided no edge is below
    * the values of its ends, as in the DTM filtration.
    *
    * @param edges
    *   the edges within `threshold`, unsorted, each once with `a < b` ([[FlagGenerator.ofEdges]] checks and builds
    *   them)
    * @param deadline
    *   per vertex, the last value at which it can join a simplex; empty for no deadline
    */
  open class FlagGenerator(
    val n: Int,
    val threshold: Double,
    val candidates: Candidates,
    edgeList: FlagGenerator.Edges,
    val deadline: Array[Double]
  ):
    private val hasDeadlines = deadline.nonEmpty

    /** The edges within `threshold`, sorted by length and then colexicographically descending: endpoints `edgeA(e) <
      * edgeB(e)`, length `edgeLength(e)`.
      */
    private val sortedEdges: (Array[Int], Array[Int], Array[Double]) =
      val (a0, b0, l0) = (edgeList.a, edgeList.b, edgeList.weight)
      val order = sortIndices(
        a0.length,
        (x, y) =>
          java.lang.Double.compare(l0(x), l0(y)) match
            case 0 =>
              if b0(x) != b0(y) then Integer.compare(b0(y), b0(x)) else Integer.compare(a0(y), a0(x))
            case c => c
      )
      (order.map(a0), order.map(b0), order.map(l0))
    val edgeA: Array[Int] = sortedEdges._1
    val edgeB: Array[Int] = sortedEdges._2
    val edgeLength: Array[Double] = sortedEdges._3

    val edgeCount: Int = edgeA.length

    /** Runs of equal diameter that came out of [[cofacets]] in the wrong tie order and were sorted. */
    var tieRunsSorted: Long = 0L

    def edges: Layer =
      val vs = new Array[Int](2 * edgeCount)
      var e = 0
      while e < edgeCount do
        vs(2 * e) = edgeA(e)
        vs(2 * e + 1) = edgeB(e)
        e += 1
      Layer(1, edgeCount, vs, Array.range(0, edgeCount))

    def diameter(layer: Layer, i: Int): Double = edgeLength(layer.root(i))

    // The current balls: `closedRows` holds the edges of length <= alpha, `openRows` those < alpha, one row of
    // `words` longs per vertex; `openEdge`/`closedEdge` are the sweep's positions in the sorted edge list.
    private val words = (n + 63) >>> 6
    private lazy val closedRows = new Array[Long](n * words)
    private lazy val openRows = new Array[Long](n * words)
    private var openEdge = 0
    private var closedEdge = 0

    // Neighbour lists sorted by distance (each list gets its edges in sorted-edge order), and per-vertex pointers:
    // `ballEnd(u)` is the end of u's closed ball at the current alpha, relative to `listStart(u)`.
    private lazy val lists: (Array[Int], Array[Int], Array[Double]) =
      val start = new Array[Int](n + 1)
      var e = 0
      while e < edgeCount do
        start(edgeA(e) + 1) += 1
        start(edgeB(e) + 1) += 1
        e += 1
      var u = 0
      while u < n do
        start(u + 1) += start(u)
        u += 1
      val fill = java.util.Arrays.copyOf(start, n)
      val vs = new Array[Int](2 * edgeCount)
      val ds = new Array[Double](2 * edgeCount)
      e = 0
      while e < edgeCount do
        val a = edgeA(e)
        val b = edgeB(e)
        vs(fill(a)) = b
        ds(fill(a)) = edgeLength(e)
        fill(a) += 1
        vs(fill(b)) = a
        ds(fill(b)) = edgeLength(e)
        fill(b) += 1
        e += 1
      (start, vs, ds)
    private lazy val listStart: Array[Int] = lists._1
    private lazy val listVertex: Array[Int] = lists._2
    private lazy val listDistance: Array[Double] = lists._3
    private lazy val ballEnd = new Array[Int](n)
    private lazy val distanceMatrix: Array[Double] =
      val m = new Array[Double](n * n)
      java.util.Arrays.fill(m, Double.PositiveInfinity)
      var e = 0
      while e < edgeCount do
        m(edgeA(e) * n + edgeB(e)) = edgeLength(e)
        m(edgeB(e) * n + edgeA(e)) = edgeLength(e)
        e += 1
      m

    private def resetSweep(): Unit = candidates match
      case Candidates.Bitsets =>
        java.util.Arrays.fill(closedRows, 0L)
        java.util.Arrays.fill(openRows, 0L)
        openEdge = 0
        closedEdge = 0
      case Candidates.NeighbourLists =>
        java.util.Arrays.fill(ballEnd, 0)

    private def setBit(rows: Array[Long], u: Int, v: Int): Unit =
      rows(u * words + (v >>> 6)) |= 1L << (v & 63)

    private def advanceBitsets(alpha: Double): Unit =
      while openEdge < edgeCount && edgeLength(openEdge) < alpha do
        setBit(openRows, edgeA(openEdge), edgeB(openEdge))
        setBit(openRows, edgeB(openEdge), edgeA(openEdge))
        openEdge += 1
      while closedEdge < edgeCount && edgeLength(closedEdge) <= alpha do
        setBit(closedRows, edgeA(closedEdge), edgeB(closedEdge))
        setBit(closedRows, edgeB(closedEdge), edgeA(closedEdge))
        closedEdge += 1

    private def closedBall(u: Int, alpha: Double): Int =
      val s = listStart(u)
      val len = listStart(u + 1) - s
      var p = ballEnd(u)
      while p < len && listDistance(s + p) <= alpha do p += 1
      ballEnd(u) = p
      p

    /** Dimension `layer.dim + 1`, from `layer` in filtration order. */
    def cofacets(layer: Layer): Layer =
      val k = layer.dim
      val width = k + 2
      val vs = layer.vertices
      val outVertices = IntBuffer()
      val outRoot = IntBuffer()
      val found = IntBuffer() // NeighbourLists: candidate w, then the position it is inserted at
      // The rows once, not through the lazy vals' accessors on each read of the candidates' loops.
      val closed = if candidates == Candidates.Bitsets then closedRows else null
      val open = if candidates == Candidates.Bitsets then openRows else null
      resetSweep()

      def emit(o: Int, w: Int, at: Int, r: Int): Unit =
        if !hasDeadlines || deadline(w) >= edgeLength(r) then emitUnchecked(o, w, at, r)

      def emitUnchecked(o: Int, w: Int, at: Int, r: Int): Unit =
        var j = 0
        while j < at do
          outVertices += vs(o + j)
          j += 1
        outVertices += w
        while j <= k do
          outVertices += vs(o + j)
          j += 1
        outRoot += r

      // Bitsets: the candidates strictly between lo and hi, largest first. Case 1 uses every vertex's closed row,
      // case 2 the closed row of u0 and the open rows of the rest, case 3 every open row.
      def emitRange(o: Int, lo: Int, hi: Int, caseNo: Int, r: Int): Unit =
        if lo + 1 < hi then
          var wi = (hi - 1) >>> 6
          val lowWord = (lo + 1) >>> 6
          while wi >= lowWord do
            var m = -1L
            var j = 0
            while j <= k && m != 0L do
              val rows = if caseNo == 1 || (caseNo == 2 && j == 0) then closed else open
              m &= rows(vs(o + j) * words + wi)
              j += 1
            if wi == (hi - 1) >>> 6 then
              val top = (hi - 1) & 63
              if top < 63 then m &= (1L << (top + 1)) - 1
            if wi == lowWord then m &= -1L << ((lo + 1) & 63)
            while m != 0L do
              val bit = 63 - java.lang.Long.numberOfLeadingZeros(m)
              emit(o, (wi << 6) + bit, caseNo - 1, r)
              m &= ~(1L << bit)
            wi -= 1

      var i = 0
      while i < layer.size do
        val r = layer.root(i)
        val alpha = edgeLength(r)
        val o = i * (k + 1)
        val u0 = vs(o)
        val u1 = vs(o + 1)
        val case2 = edgeA(r) == u0
        val case3 = case2 && edgeB(r) == u1
        val case3Top = if k == 1 then n else vs(o + 2)
        candidates match
          case Candidates.Bitsets =>
            advanceBitsets(alpha)
            if case3 then emitRange(o, u1, case3Top, 3, r)
            if case2 then emitRange(o, u0, u1, 2, r)
            emitRange(o, -1, u0, 1, r)
          case Candidates.NeighbourLists =>
            var smallest = vs(o)
            var smallestSize = closedBall(smallest, alpha)
            var j = 1
            while j <= k do
              val size = closedBall(vs(o + j), alpha)
              if size < smallestSize then
                smallest = vs(o + j)
                smallestSize = size
              j += 1
            found.clear()
            val s = listStart(smallest)
            var p = 0
            while p < smallestSize do
              val w = listVertex(s + p)
              val at =
                if w < u0 then 0
                else if case2 && w > u0 && w < u1 then 1
                else if case3 && w > u1 && w < case3Top then 2
                else -1
              if at >= 0 then
                var ok = true
                var q = 0
                while ok && q <= k do
                  val u = vs(o + q)
                  if u != smallest || at > 0 then
                    val d = distanceMatrix(w * n + u)
                    ok = if at == 0 || (at == 1 && q == 0) then d <= alpha else d < alpha
                  q += 1
                if ok then
                  found += w
                  found += at
              p += 1
            // largest candidate first
            val order = sortIndices(found.size / 2, (x, y) => Integer.compare(found(2 * y), found(2 * x)))
            var f = 0
            while f < order.length do
              emit(o, found(2 * order(f)), found(2 * order(f) + 1), r)
              f += 1
        i += 1

      val out = Layer(k + 1, outRoot.size, outVertices.result, outRoot.result)
      sortTieRuns(out)
      out

    /** Colexicographic comparison of simplices `x` and `y` of `layer`: the larger top vertex wins, then the next. */
    def colexCompare(layer: Layer, x: Int, y: Int): Int =
      val w = layer.dim + 1
      var j = layer.dim
      var c = 0
      while c == 0 && j >= 0 do
        c = Integer.compare(layer.vertices(x * w + j), layer.vertices(y * w + j))
        j -= 1
      c

    // Every run of equal diameter must be colexicographically descending; sort the runs that are not.
    private def sortTieRuns(layer: Layer): Unit =
      val w = layer.dim + 1
      var start = 0
      while start < layer.size do
        val alpha = diameter(layer, start)
        var end = start + 1
        var inOrder = true
        while end < layer.size && diameter(layer, end) == alpha do
          if colexCompare(layer, end - 1, end) <= 0 then inOrder = false
          end += 1
        if !inOrder then
          tieRunsSorted += 1
          val order = sortIndices(end - start, (x, y) => colexCompare(layer, start + y, start + x))
          val vs = java.util.Arrays.copyOfRange(layer.vertices, start * w, end * w)
          val rs = java.util.Arrays.copyOfRange(layer.root, start, end)
          var t = 0
          while t < order.length do
            System.arraycopy(vs, order(t) * w, layer.vertices, (start + t) * w, w)
            layer.root(start + t) = rs(order(t))
            t += 1
        start = end

  object FlagGenerator:

    /** The edges of a graph as three parallel arrays, `a(i) < b(i)` with weight `weight(i)`, in no particular order. */
    final case class Edges(a: Array[Int], b: Array[Int], weight: Array[Double])

    /** A generator for the flag complex of the graph on `0 until n` with the edges `(a(i), b(i))` of weight
      * `weight(i)`. Edges heavier than `threshold`, or than the deadline of one of their ends, are left out, since they
      * would be no simplices; the ends may come in either order.
      *
      * @throws IllegalArgumentException
      *   for an end outside `0 until n`, a loop, an edge listed twice, or a weight that is not a number
      */
    def ofEdges(
      n: Int,
      a: Array[Int],
      b: Array[Int],
      weight: Array[Double],
      threshold: Double,
      candidates: Candidates = Candidates.Bitsets,
      deadline: Array[Double] = Array.emptyDoubleArray
    ): FlagGenerator =
      require(a.length == b.length && a.length == weight.length, "the edge arrays must have the same length")
      require(deadline.isEmpty || deadline.length == n, s"one deadline per vertex (${n}), got ${deadline.length}")
      val seen = mutable.HashSet.empty[Long]
      val keptA = IntBuffer()
      val keptB = IntBuffer()
      val keptWeight = DoubleBuffer()
      var i = 0
      while i < a.length do
        val (lo, hi) = (math.min(a(i), b(i)), math.max(a(i), b(i)))
        require(lo >= 0 && hi < n, s"edge ${a(i)} ${b(i)} has an end outside 0 until $n")
        require(lo != hi, s"edge ${a(i)} ${b(i)} is a loop")
        require(!weight(i).isNaN, s"edge ${a(i)} ${b(i)} has weight NaN")
        require(seen.add(lo.toLong * n + hi), s"edge $lo $hi is listed twice")
        val alive = deadline.isEmpty || weight(i) <= math.min(deadline(lo), deadline(hi))
        if weight(i) <= threshold && alive then
          keptA += lo
          keptB += hi
          keptWeight += weight(i)
        i += 1
      new FlagGenerator(n, threshold, candidates, Edges(keptA.result, keptB.result, keptWeight.result), deadline)

    /** The edges of the complete graph on `0 until n` with `distance` as weight, those within `threshold`. The distance
      * is asked as `distance(larger, smaller)`, the lower triangle that ripser.cpp and [[ExplicitMetricSpace]] read,
      * and which is along a row of a cached matrix.
      */
    def edgesWithin(n: Int, distance: (Int, Int) => Double, threshold: Double): Edges =
      val as = IntBuffer()
      val bs = IntBuffer()
      val ls = DoubleBuffer()
      var b = 1
      while b < n do
        var a = 0
        while a < b do
          val d = distance(b, a)
          if d <= threshold then
            as += a
            bs += b
            ls += d
          a += 1
        b += 1
      Edges(as.result, bs.result, ls.result)

  /** Builds the layers of the Vietoris-Rips complex of the `n` points with the given distance, up to `threshold`: the
    * flag complex of the graph with an edge for every pair within `threshold` ([[FlagGenerator]]).
    */
  open class Generator(
    n: Int,
    distance: (Int, Int) => Double,
    threshold: Double,
    candidates: Candidates = Candidates.Bitsets
  ) extends FlagGenerator(
        n,
        threshold,
        candidates,
        FlagGenerator.edgesWithin(n, distance, threshold),
        Array.emptyDoubleArray
      )

  // Runs of this many indices are sorted by insertion before the merging starts.
  private val InsertionBlock = 16

  /** `0 until count` stably sorted by `compare`: a merge sort on primitive indices, over insertion-sorted blocks, whose
    * merge of two neighbours moves only the part of each that overlaps the other. A sequence that is nearly in order,
    * as the runs of equal diameter the generator emits are, costs little more at a block size above its disorder than
    * the comparisons that find the overlap.
    */
  inline def sortIndices(count: Int, inline compare: (Int, Int) => Int): Array[Int] =
    var src = Array.range(0, count)
    var from = 0
    while from < count do
      val until = math.min(from + InsertionBlock, count)
      var i = from + 1
      while i < until do
        val x = src(i)
        var j = i - 1
        while j >= from && compare(src(j), x) > 0 do
          src(j + 1) = src(j)
          j -= 1
        src(j + 1) = x
        i += 1
      from = until
    var dst = new Array[Int](count)
    var width = InsertionBlock
    while width < count do
      var lo = 0
      while lo < count do
        val mid = math.min(lo + width, count)
        val hi = math.min(lo + 2 * width, count)
        // Only the left elements above the right half's first and the right elements below the left half's last
        // change places: `from` is the first of the former and `until` one past the last of the latter.
        var from = mid
        var until = mid
        if mid < hi then
          var a = lo
          var b = mid
          while a < b do // the first left element above src(mid)
            val m = (a + b) >>> 1
            if compare(src(m), src(mid)) > 0 then b = m else a = m + 1
          from = a
          a = mid
          b = hi
          while a < b do // one past the last right element below src(mid - 1)
            val m = (a + b) >>> 1
            if compare(src(m), src(mid - 1)) < 0 then a = m + 1 else b = m
          until = a
        System.arraycopy(src, lo, dst, lo, from - lo)
        var i = from
        var j = mid
        var t = from
        while t < until do
          if i < mid && (j >= until || compare(src(i), src(j)) <= 0) then
            dst(t) = src(i)
            i += 1
          else
            dst(t) = src(j)
            j += 1
          t += 1
        System.arraycopy(src, until, dst, until, hi - until)
        lo = hi
      val swap = src
      src = dst
      dst = swap
      width *= 2
    src

  /** A growable `Array[Int]`. */
  open class IntBuffer:
    private var data = new Array[Int](16)
    var size: Int = 0
    def +=(x: Int): Unit =
      if size == data.length then data = java.util.Arrays.copyOf(data, math.max(16, data.length * 2))
      data(size) = x
      size += 1
    def apply(i: Int): Int = data(i)
    def clear(): Unit = size = 0
    def result: Array[Int] = java.util.Arrays.copyOf(data, size)

  /** A growable `Array[Double]`. */
  open class DoubleBuffer:
    private var data = new Array[Double](16)
    var size: Int = 0
    def +=(x: Double): Unit =
      if size == data.length then data = java.util.Arrays.copyOf(data, math.max(16, data.length * 2))
      data(size) = x
      size += 1
    def result: Array[Double] = java.util.Arrays.copyOf(data, size)
